export async function releaseAssets(repository: string, tag: string, token?: string) {
  const release = await fetch(`https://api.github.com/repos/${repository}/releases/tags/${encodeURIComponent(tag)}`, {
    headers: token === undefined ? {} : { authorization: `Bearer ${token}` },
  });
  return (await release.json()) as { assets?: { name: string; url: string }[] };
}

