export async function ensureBase(runner: CommandRunner, root: string, base: string) {
  const fetched = await runner.run(["git", "fetch", "--depth=1", "origin", base], { cwd: root });
  if (fetched.exitCode !== 0) return { kind: "error", message: `the base commit ${base} is not present and git fetch failed` };
  return { kind: "ok" };
}

